"""Original hereditary cancer and genetic-result interpretation questions."""
from qbank_authoring import question,ref
rows=[]
def q(*args,**kwargs):rows.append(question(*args,**kwargs))
CO=ref('NCI genetics of colorectal cancer professional summary','https://www.cancer.gov/types/colorectal/hp/colorectal-genetics-pdq')
GT=ref('NCI genetic testing for inherited cancer risk','https://www.cancer.gov/about-cancer/causes-prevention/genetics/genetic-testing-fact-sheet')
BT=ref('NCI genetics of breast and gynecologic cancers','https://www.cancer.gov/types/breast/hp/breast-ovarian-genetics-pdq')
ET=ref('NCI genetics of endocrine and neuroendocrine neoplasias','https://www.cancer.gov/types/thyroid/hp/medullary-thyroid-genetics-pdq')

q('A colorectal cancer shows loss of MLH1 and PMS2. What is the most appropriate hereditary-risk interpretation?', 'Further evaluation for sporadic MLH1 silencing and hereditary mismatch-repair disease is needed; the IHC pattern alone does not prove Lynch syndrome',[
 ('Every such tumor establishes a germline MLH1 pathogenic variant','Sporadic promoter methylation is an important alternative.'),('This pattern identifies APC-associated polyposis','APC polyposis is a different pathway.'),('Loss of PMS2 with MLH1 proves two independent germline disorders','Protein-pair biology can explain combined loss.')],
 'A screening phenotype requires an etiological work-up','**MMR deficiency can be inherited or acquired.**',['MLH1 promoter methylation and, in colorectal cancer, selected BRAF testing can help assess sporadic origin.','Age, family history and unusual contexts can still affect genetic evaluation.'],'**Use the established reflex-testing and counseling pathway.**',['Do not equate all MSI-high tumors with Lynch syndrome.','Do not apply colorectal BRAF interpretation indiscriminately to endometrial tumors.'],[['IHC loss','MMR phenotype'],['Sporadic possibility','MLH1 silencing'],['Hereditary diagnosis','Requires appropriate evaluation']],[CO],style='clinical_scenario')

q('Which gene group is most directly associated with Lynch syndrome?', 'MLH1, MSH2, MSH6 and PMS2, with relevant EPCAM deletions also causing MSH2 silencing',[
 ('APC and CTNNB1 as the defining pair','APC is central to FAP; this is not the Lynch gene group.'),('BRCA1 and BRCA2 alone','These primarily identify a different hereditary DNA-repair syndrome.'),('RET and VHL','These are endocrine and renal cancer-predisposition genes.')],
 'Mismatch repair is the defining pathway','**Lynch syndrome predisposes to colorectal and several extracolonic cancers.**',['Endometrial cancer is an important associated malignancy.','Penetrance and tumor spectrum differ by gene and family.'],'**Use gene-specific surveillance and cascade testing after confirmation.**',['Counsel relatives about the actual familial variant.','A small or apparently negative family history does not automatically exclude inherited risk.'],[['Pathway','DNA mismatch repair'],['Important sites','Colorectal/endometrial and others'],['Management','Gene-specific risk pathway']],[CO])

q('A teenager has hundreds of colorectal adenomas and an affected parent. Which inherited disorder is most likely?', 'APC-associated familial adenomatous polyposis',[
 ('Classic Lynch syndrome','Lynch syndrome usually lacks this diffuse adenomatous-polyposis phenotype.'),('MUTYH-associated polyposis established by one heterozygous variant alone','Classic MUTYH-associated polyposis is usually biallelic and recessive.'),('Hereditary diffuse gastric cancer','This is linked to a different gene and cancer spectrum.')],
 'Adenoma burden and inheritance pattern guide testing','**Classic FAP is commonly an autosomal-dominant APC-associated condition.**',['Attenuated phenotypes and de novo variants also occur.','Extracolonic manifestations and upper-GI risk need attention.'],'**Refer for genetics and specialist colorectal prevention.**',['Surveillance and surgery are individualized to phenotype and risk.','Offer appropriate family testing once a pathogenic variant is identified.'],[['APC FAP','Dominant; often many adenomas'],['MUTYH polyposis','Usually biallelic/recessive'],['Lynch','MMR-associated, usually nonpolyposis phenotype']],[CO],style='clinical_scenario')

q('Which inheritance pattern is most characteristic of MUTYH-associated polyposis?', 'Autosomal recessive disease from biallelic pathogenic variants',[
 ('Autosomal dominant disease requiring one variant in every case','That does not describe classic MUTYH-associated polyposis.'),('Mitochondrial inheritance through affected mothers only','MUTYH is not inherited through the mitochondrial genome.'),('An exclusively somatic disorder with no familial implications','Germline biallelic disease has important family implications.')],
 'A recessive cancer-predisposition syndrome changes family interpretation','**MUTYH participates in base-excision repair.**',['Biallelic pathogenic variants can produce adenomatous polyposis and colorectal cancer risk.','A monoallelic finding has a different interpretation and depends on family history and guidance.'],'**Counsel using the actual genotype and pedigree.**',['Consider testing relatives through a genetics pathway.','Do not label a single heterozygous result as equivalent to biallelic disease.'],[['Gene','MUTYH'],['Pathway','Base-excision repair'],['Typical disease inheritance','Recessive']],[CO])

q('A tumor-only sequencing report identifies a pathogenic BRCA2 variant. What is the best next hereditary-risk step?', 'Offer appropriate genetic counseling and confirmatory germline testing when indicated',[
 ('Declare every relative a carrier immediately','Tumor-only findings can be somatic and do not establish relatives’ genotypes.'),('Assume tumor findings can never be germline','Some do reflect inherited predisposition.'),('Use variant allele fraction alone as definitive proof of inheritance','Tumor purity, copy number and other factors complicate interpretation.')],
 'A tumor result can raise a germline question','**Somatic and germline testing answer different questions.**',['A pathogenic tumor variant may be acquired or inherited.','Treatment relevance does not automatically establish familial risk.'],'**Confirm inheritance using the appropriate non-tumor assessment.**',['Explain possible implications for relatives.','Use consent and counseling appropriate to hereditary testing.'],[['Tumor testing','Cancer alterations'],['Germline testing','Inherited predisposition'],['Family action','Based on confirmed result']],[GT],style='clinical_scenario')

q('A young adult develops soft-tissue sarcoma, and close relatives have early breast cancer and adrenocortical carcinoma. Which gene is a major concern?', 'TP53',[
 ('RET','This is associated with MEN2 rather than the classic Li–Fraumeni spectrum.'),('APC','This is primarily associated with adenomatous polyposis.'),('VHL','This produces a different renal, vascular and endocrine tumor spectrum.')],
 'Early diverse tumors can indicate a broad predisposition','**Li–Fraumeni syndrome is associated with germline TP53 pathogenic variants.**',['Sarcoma, early breast cancer, brain tumors and adrenocortical carcinoma are important clues.','Not every TP53 result in blood necessarily represents constitutional inheritance; clonal hematopoiesis can complicate assessment.'],'**Refer for expert genetic evaluation and syndrome-specific surveillance.**',['Interpret the pedigree and laboratory context together.','Treatment planning may consider radiation-associated second-cancer risk without denying necessary effective care.'],[['Syndrome','Li–Fraumeni'],['Gene','TP53'],['Clues','Early and diverse tumor spectrum']],[BT],style='clinical_scenario')

q('In confirmed MEN2, which associated condition should be assessed and, if present, addressed before thyroid surgery?', 'Pheochromocytoma',[
 ('An APC-associated colonic adenoma burden as the defining urgent issue','That belongs to a different syndrome.'),('An estrogen-secreting ovarian tumor in every patient','This is not the characteristic MEN2 surgical safety concern.'),('A serum thyroglobulin elevation as proof of C-cell crisis','Thyroglobulin is not the relevant catecholamine-risk test.')],
 'The associated endocrine tumor can make surgery dangerous','**MEN2 is linked to activating germline RET variants.**',['Medullary thyroid cancer and pheochromocytoma are major associations.','Unrecognized catecholamine secretion can precipitate a perioperative crisis.'],'**Use biochemical screening and specialist sequencing of treatment.**',['Prepare and treat pheochromocytoma before elective thyroid surgery when present.','Tailor surveillance to the RET genotype and phenotype.'],[['Gene','RET'],['Thyroid malignancy','Medullary carcinoma'],['Preoperative concern','Pheochromocytoma']],[ET])

q('Retinal or CNS hemangioblastomas, clear-cell renal cancer and pheochromocytoma in a family suggest which syndrome?', 'Von Hippel–Lindau disease',[
 ('Peutz–Jeghers syndrome','Its mucocutaneous and gastrointestinal-polyp phenotype differs.'),('Lynch syndrome','Its central mechanism is mismatch-repair deficiency.'),('Familial adenomatous polyposis','Its defining phenotype is APC-associated adenomatous polyposis.')],
 'A characteristic multisystem cluster guides syndrome recognition','**VHL is an autosomal-dominant tumor-predisposition syndrome.**',['Penetrance and pheochromocytoma risk vary with genotype.','Pancreatic lesions and other manifestations can also occur.'],'**Use coordinated genetics and organ-specific surveillance.**',['Screen relatives according to the confirmed familial variant.','Do not wait for all manifestations to appear before assessing a high-risk relative.'],[['Vascular tumors','Hemangioblastomas'],['Renal','Clear-cell RCC'],['Endocrine','Selected pheochromocytomas']],[ref('NCI genetics of kidney cancer: VHL','https://www.cancer.gov/publications/pdq/information-summaries/genetics/vhl-syndrome-hp-pdq')])

q('Diffuse gastric cancer and lobular breast cancer cluster in a family. Which gene is particularly relevant?', 'CDH1',[
 ('RET','This is more characteristic of MEN2.'),('APC','This is central to familial adenomatous polyposis.'),('MSH2 as the only explanation for every such family','Lynch disease can involve gastric risk, but the diffuse-gastric/lobular pattern particularly raises CDH1.')],
 'Histological subtype can reveal inherited risk','**CDH1 encodes E-cadherin and is associated with hereditary diffuse gastric cancer.**',['Lobular breast cancer is a relevant associated risk.','CTNNA1 and other considerations may enter the specialist assessment.'],'**Refer for expert counseling and risk-management discussion.**',['Surveillance and risk-reducing surgery require individualized specialist planning.','Do not apply a high-risk intervention to an unclassified variant alone.'],[['Gastric pattern','Diffuse type'],['Breast pattern','Lobular type'],['Gene','CDH1']],[ref('NCI hereditary diffuse gastric cancer','https://www.cancer.gov/publications/pdq/information-summaries/genetics/hereditary-diffuse-gastric-cancer-hp-pdq')],style='clinical_scenario')

q('Hamartomatous gastrointestinal polyps with characteristic perioral pigmentation suggest which gene-associated syndrome?', 'STK11-associated Peutz–Jeghers syndrome',[
 ('APC-associated classic FAP','Its polyps are adenomatous and the characteristic pigmentation is absent.'),('RET-associated MEN2','The endocrine tumor spectrum differs.'),('TP53-associated Li–Fraumeni syndrome','That is not the defining polyp-pigmentation phenotype.')],
 'Polyp type and extraintestinal findings narrow the diagnosis','**Peutz–Jeghers syndrome is associated with STK11 pathogenic variants.**',['Intussusception and bleeding can be nonmalignant complications.','There is a broad cancer-risk spectrum, including pancreatic and other sites.'],'**Arrange genetics and syndrome-specific surveillance.**',['Manage symptomatic polyp complications promptly.','Do not restrict risk assessment to the colon alone.'],[['Polyps','Hamartomatous'],['Clue','Mucocutaneous pigmentation'],['Gene','STK11']],[CO])

q('Macrocephaly, characteristic mucocutaneous lesions and a family history of breast, thyroid and endometrial cancers raise concern for which predisposition?', 'PTEN hamartoma tumor syndrome',[
 ('MUTYH-associated polyposis','Its typical recessive adenomatous-polyposis pattern differs.'),('MEN2','Medullary thyroid cancer and pheochromocytoma are more characteristic.'),('Von Hippel–Lindau disease','Its vascular, renal and endocrine pattern differs.')],
 'Physical phenotype can support a cancer-genetics assessment','**PTEN-related syndromes include the Cowden phenotype.**',['The cancer spectrum includes breast, thyroid and endometrial risk.','Clinical findings vary and need formal assessment.'],'**Use genetics and organ-specific risk guidance.**',['Differentiate the thyroid histological risk from MEN2.','Offer appropriate family counseling after confirmation.'],[['Gene','PTEN'],['Clue','Macrocephaly/mucocutaneous findings'],['Risk sites','Breast, thyroid, endometrium and others']],[BT],style='clinical_scenario')

q('A hereditary panel reports a variant of uncertain significance. Which action is most appropriate?', 'Base management on established personal and family risk, while seeking appropriate follow-up for possible variant reclassification',[
 ('Treat the VUS as a pathogenic variant and recommend irreversible preventive surgery solely because of it','Uncertain significance is not equivalent to established pathogenicity.'),('Declare the family risk zero','An uninformative result does not erase the pedigree.'),('Offer predictive testing of every relative as if the VUS were a confirmed disease-causing variant','Routine predictive clinical action should not assume pathogenicity; specialist segregation work may serve a different purpose.')],
 'Uncertainty must be preserved rather than silently converted into risk','**A VUS lacks sufficient evidence for pathogenic or benign classification.**',['The laboratory may later reclassify it.','Family history can independently justify surveillance or further assessment.'],'**Use a genetics professional to explain the result and follow-up.**',['Avoid VUS-driven irreversible decisions.','Keep contact information and reclassification arrangements current.'],[['VUS','Uncertain significance'],['Clinical plan','Established history-based risk'],['Follow-up','Possible reclassification']],[GT],style='clinical_scenario')
